<?php $title='Open roles'; require 'header.php'; ?>
<main class="container"><div class="page-intro"><div><span class="eyebrow">CAREERS</span><h1>Open roles</h1><p>Find the team, challenge and working style that fits you.</p></div><div class="search-box"><input id="roleSearch" placeholder="Search roles, teams, locations…"></div></div>
<div class="job-layout"><aside class="filters"><label>Department</label><select id="dept"><option value="">All departments</option><?php $ds=db()->query("SELECT DISTINCT department FROM jobs WHERE status='open' ORDER BY department"); while($d=$ds->fetch_assoc()): ?><option><?=e($d['department'])?></option><?php endwhile; ?></select><label>Work mode</label><select id="mode"><option value="">Any</option><option>Remote</option><option>Hybrid</option><option>On-site</option></select></aside>
<section class="jobs-list" id="jobsList"><?php $rs=db()->query("SELECT * FROM jobs WHERE status='open' ORDER BY created_at DESC"); while($j=$rs->fetch_assoc()): ?><article class="job-row" data-text="<?=e(strtolower($j['title'].' '.$j['department'].' '.$j['location']))?>" data-dept="<?=e($j['department'])?>" data-mode="<?=e($j['work_mode'])?>"><div><span class="role-dept"><?=e($j['department'])?></span><h2><?=e($j['title'])?></h2><p><?=e($j['description'])?></p></div><div class="job-side"><span><?=e($j['location'])?></span><span><?=e($j['work_mode'])?> · <?=e($j['employment_type'])?></span><a href="job.php?id=<?=$j['id']?>">See role →</a></div></article><?php endwhile; ?></section></div></main>
<script>
const s=document.getElementById('roleSearch'),d=document.getElementById('dept'),m=document.getElementById('mode');
function filter(){let q=s.value.toLowerCase(),dd=d.value,mm=m.value;document.querySelectorAll('.job-row').forEach(x=>x.style.display=(!q||x.dataset.text.includes(q))&&(!dd||x.dataset.dept===dd)&&(!mm||x.dataset.mode===mm)?'grid':'none')}
[s,d,m].forEach(x=>x.addEventListener('input',filter));
</script><?php require 'footer.php'; ?>